 const driverNames={home:'Início',ride:'Vale a corrida?',journey:'Minha jornada',wallet:'Carteira',shop:'Minha loja',more:'Mais',care:'Meu carro e manutenção',inspection:'Vistoria',docs:'Contrato e documentos',support:'Suporte',goals:'Metas e custos'};
 function driverView(){return heading('RODAVOLT MOTORISTA','Mais controle de quem está ao volante.','Um espaço para decidir melhor, cuidar do carro e acompanhar cada compromisso.')+`<div class="driver-layout"><section class="mobile-app" aria-label="Aplicativo do motorista"><div class="mobile-brand"><span>RODAVOLT MOTORISTA</span><span class="avatar">MO</span></div><h2>${driverPage==='home'?'Olá, Marcos.':driverNames[driverPage]}</h2><p class="mobile-subtitle">${driverPage==='home'?'Seu dia pode começar com um plano.':'RV-001 · LOC-001 · conta demonstrativa'}</p><div id="driver-body">${driverBody()}</div><nav class="driver-tabs" aria-label="Navegação do motorista">${[['home','Início'],['ride','Corrida'],['wallet','Carteira'],['shop','Loja'],['more','Mais']].map(([key,label])=>`<button type="button" data-driver-page="${key}" aria-pressed="${key===driverPage||(key==='more'&&['care','inspection','docs','support','goals','journey'].includes(driverPage))}">${label}</button>`).join('')}</nav></section><aside class="driver-context"><span class="eyebrow">DO SEU OBJETIVO À SUA DECISÃO</span><h2>Ganhar bem começa<br>por entender a conta.</h2><p>A oferta precisa pagar o trajeto completo, seu tempo e os custos de rodar. Aqui o motorista compara com suas metas, decide e registra — sem misturar seus ganhos pessoais com o caixa da locadora.</p><div class="driver-menu">${[['ride','Vale a corrida?','R$/km, ganho por hora e oferta mínima'],['goals','Metas e custos','Objetivo diário, combustível e aluguel'],['journey','Minha jornada','Ganhos, despesas e km por dia'],['wallet','Carteira','Aluguel, comprovantes e repasses'],['care','Meu carro','Revisão, km e pedidos de manutenção'],['inspection','Vistoria','Checklist, hodômetro e observações'],['shop','Minha loja','Perfumes, acessórios e comissão'],['docs','Meus documentos','Contrato, condições e termos'],['support','Suporte','Pedidos e respostas no histórico']].map(([key,title,desc])=>`<button type="button" data-driver-page="${key}" aria-pressed="${driverPage===key}">${title}<small>${desc}</small></button>`).join('')}</div><div class="notice gap">A análise de corrida é manual e considera os valores informados pelo motorista. Não lê a tela nem aceita ou recusa corridas no Uber/99. Use antes de iniciar o deslocamento.</div></aside></div>`;}
 function driverBody(){const p=ops.personal.settings,personal=D.daySummary(ops.personal.journeys,p),s=M.shopSummary(ops),charge=ops.charges.find(c=>c.status!=='paid');
 if(driverPage==='home')return `<div class="personal-summary"><small>SUA META DE GANHO LÍQUIDO POR DIA</small><strong>${money(p.goalDay)}</strong><small>Depois de combustível, outras despesas e aluguel rateado.</small></div><div class="quick-grid"><button type="button" data-driver-page="ride">Vale a corrida?<small>Compare a oferta com sua meta</small></button><button type="button" data-driver-page="journey">Fechar minha jornada<small>Ganhos, despesas e km do dia</small></button><button type="button" data-driver-page="wallet">Meu aluguel<small>${charge?money(charge.amount)+' · '+date(charge.date):'Cobranças conferidas'}</small></button><button type="button" data-driver-page="shop">Vender na minha loja<small>Perfumes e acessórios</small></button></div><div class="gap">${panel('Seu resumo pessoal',row('Jornadas registradas',personal.days+' dia(s)')+row('Saldo após aluguel rateado',cash(personal.net),'Somente os dias que você registrou.')+row('Comissão a acertar',cash(s.commission))+link('Ajustar minhas metas e custos →','driver-goals'))}</div><div class="gap">${panel('Cuidado com seu carro',row('Próxima revisão',num(Math.max(0,ops.vehicle.nextKm-ops.vehicle.km))+' km','Hodômetro informado: '+num(ops.vehicle.km)+' km.')+btn('Pedir manutenção','driver-care'))}</div>`;
 if(driverPage==='ride')return rideView();
 if(driverPage==='goals')return `<form id="goals-form"><div class="fields">${Object.entries({goalDay:'Meta líquida por dia · R$',minNetKm:'Mínimo líquido por km · R$',minNetHour:'Mínimo líquido por hora · R$',fuelPrice:'Combustível por litro · R$',efficiency:'Consumo médio · km/l',otherPerKm:'Outros custos seus por km · R$',weeklyRent:'Aluguel semanal · R$',workDays:'Dias trabalhados por semana',hoursDay:'Horas planejadas por dia',plannedKmDay:'Km planejados por dia'}).map(([key,label])=>input(key,label,p[key],`type="number" min="${D.limits[key][0]}" max="${D.limits[key][1]}" step="${key==='workDays'?'1':'any'}" required`)).join('')}</div><div class="form-actions"><button type="submit" class="btn primary">Salvar minhas metas</button></div><p class="caption">Inclua em “outros custos” somente os que você paga, para não duplicar custos já cobertos pelo aluguel. O valor da oferta deve ser o que você receberá, sem descontar a taxa do app outra vez.</p></form>`;
 if(driverPage==='journey')return `<div class="personal-summary"><small>SALDO DOS DIAS REGISTRADOS</small><strong>${cash(personal.net)}</strong><small>Recebido − combustível − outras despesas − aluguel rateado.</small></div>${panel('Fechar ou corrigir um dia',`<form id="journey-form"><div class="fields">${input('date','Dia da jornada','2027-01-25','type="date" required')}${input('amount','Ganhos recebidos · R$',400,'type="number" min="0" step=".01" required')}${input('fuel','Combustível pago · R$',85,'type="number" min="0" step=".01" required')}${input('other','Outras despesas · R$',15,'type="number" min="0" step=".01" required')}${input('km','Km totais rodados',180,'type="number" min="0" step="any" required')}${input('hours','Horas trabalhadas',8,'type="number" min="0" max="24" step="any" required')}</div><div class="form-actions"><button type="submit" class="btn primary">Salvar fechamento do dia</button></div><p class="caption">Salvar de novo a mesma data corrige o registro. O aluguel é rateado uma vez por dia, sem duplicar.</p></form>`)}<div class="gap">${panel('Meus resultados',row('Recebido',cash(personal.amount))+row('Combustível e outras despesas',cash(personal.fuel+personal.other))+row('Aluguel rateado',cash(personal.rent))+row('Saldo líquido',cash(personal.net),'',true)+row('Líquido por km',personal.netKm===null?'Sem jornada':cash(personal.netKm))+row('Líquido por hora',personal.netHour===null?'Sem jornada':cash(personal.netHour)))}</div><div class="gap">${panel('Histórico pessoal',ops.personal.journeys.length?ops.personal.journeys.map(j=>row(date(j.date),cash(D.daySummary([j],p).net),num(j.km)+' km · '+num(j.hours)+' horas')).join(''):'<p class="caption">Nenhum dia registrado ainda. Sua jornada não entra como receita da locadora.</p>')}</div>`;
 if(driverPage==='wallet')return `${panel('Seu aluguel semanal',ops.charges.map(c=>row(c.id+' · '+date(c.date),cash(c.amount),c.status==='paid'?'Recebimento conferido':ops.proofs.some(pr=>pr.chargeId===c.id&&pr.status==='pending')?'Comprovante em análise':'Em aberto')).join('')+(charge&&!ops.proofs.some(pr=>pr.chargeId===charge.id&&pr.status==='pending')?btn('Enviar comprovante de exemplo','proof','primary',`data-id="${charge.id}"`):''))}<div class="gap">${panel('Comissão e repasse da loja',row('Comissão das vendas em acerto',cash(s.commission))+row('Vendas a repassar à empresa',cash(s.remittance),'Quando você recebeu em dinheiro; comissão já descontada.')+row('Comissão a pagar pela empresa',cash(s.payable),'Quando o dinheiro da venda ficou com a empresa.')+row('Caução','Conforme contrato','Não é receita nem saldo livre para descontar.')+btn('Ver contrato e responsabilidades','contract'))}</div><p class="caption">Comprovante ilustrativo: sem Pix nem upload real. A gestão precisa conferir para confirmar o recebimento.</p>`;
 if(driverPage==='shop')return `${panel('Seu kit, com preço e estoque',ops.book.products.map(p=>row(esc(p.name),cash(p.price),p.kit+' un. no carro · custo e comissão preservados por venda.')).join(''))}<div class="gap">${panel('Vender um produto',saleForm())}</div><div class="gap">${panel('Comissão e reposição',row('Comissão a acertar',cash(s.commission))+row('Vendas abertas',String(s.sales))+`<form id="stock-request-form"><div class="fields">${select('productId','Produto para repor','perfume',ops.book.products.map(p=>[p.id,p.name]))}${input('qty','Quantidade',2,'type="number" min="1" step="1" required')}</div><div class="form-actions"><button type="submit" class="btn">Pedir reposição</button></div></form>`)}</div>`;
 if(driverPage==='care')return `${panel('RV-001 · '+ops.vehicle.model,row('Hodômetro',num(ops.vehicle.km)+' km')+row('Próxima preventiva',num(ops.vehicle.nextKm)+' km')+row('Situação',ops.vehicle.status==='maintenance'?'Em manutenção':'Vínculo ativo de exemplo')+btn('Fazer vistoria','driver-inspection'))}<div class="gap">${panel('Pedir manutenção',`<form id="maintenance-request-form">${select('priority','Impacto para trabalhar','normal',[['normal','Carro rodando · avaliar serviço'],['urgent','Carro parado · atendimento prioritário']])}<label class="field gap">Descreva o problema<textarea name="note" required rows="3" maxlength="500" placeholder="O que aconteceu e quando começou?"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Abrir solicitação</button></div></form>`)}</div><div class="gap">${panel('Acompanhar pedidos',driverRequests('maintenance'))}</div>`;
 if(driverPage==='inspection')return panel('Checklist de vistoria',`<form id="inspection-form">${input('km','Hodômetro atual · km',ops.vehicle.km,`type="number" min="${ops.vehicle.km}" step="1" required`)}${['Pneus e itens de segurança conferidos','Lataria, vidros e luzes conferidos','Interior, acessórios e combustível conferidos','Kit da loja contado e conferido'].map((text,i)=>`<label class="check"><input type="checkbox" name="check${i}" required>${text}</label>`).join('')}<label class="field gap">Observações e avarias percebidas<textarea name="note" rows="3" maxlength="500"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Registrar checklist</button></div><p class="caption">Registra checklist e km na demonstração. Fotos, assinatura e comparação de entrega/devolução precisam de armazenamento privado na versão operacional.</p></form>`);
 if(driverPage==='docs')return panel('Documentos do seu vínculo',contractBody()+row('Termos disponíveis','Contrato, kit comercial e vistorias','A aplicação operacional disponibilizará as versões assinadas e os arquivos privados por vínculo.'));
 if(driverPage==='support')return `${panel('Conversar com a RODAVOLT',`<form id="support-form">${select('subject','Assunto','Contrato',[['Contrato','Contrato'],['Pagamento','Pagamento'],['Loja','Loja'],['Carro','Carro']])}<label class="field gap">Sua mensagem<textarea name="note" required rows="3" maxlength="500"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Registrar chamado</button></div></form>`)}<div class="gap">${panel('Meus protocolos',driverRequests('support'))}</div>`;
 return `<div class="quick-grid">${[['goals','Metas e custos'],['journey','Minha jornada'],['care','Meu carro e manutenção'],['inspection','Vistoria'],['docs','Contrato e documentos'],['support','Suporte']].map(([key,title])=>`<button type="button" data-driver-page="${key}">${title}<small>Abrir →</small></button>`).join('')}</div><p class="caption">Dados pessoais da jornada separados dos recebimentos da empresa. Esta demonstração não substitui autenticação e permissões individuais no servidor.</p>`;
 }
 function driverRequests(type){const list=ops.requests.filter(r=>r.type===type);return list.length?list.map(r=>row(r.id,tag(r.status==='open'?'Aberto':r.status==='answered'?'Respondido':r.status==='delivered'?'Entregue':'Em atendimento',r.status==='open'?'amber':'green'),esc(r.note))+(r.reply?`<div class="notice gap"><strong>Resposta no exemplo</strong><br>${esc(r.reply)}</div>`:'')).join(''):'<p class="caption">Ainda sem solicitações desse tipo.</p>';}
 function rideView(){rideResult=D.evaluate(ride,ops.personal.settings);return `<div class="notice">A oferta deve ser o valor que você receberá. A distância inclui o caminho até o passageiro e eventual reposicionamento.</div><form id="ride-form" class="gap"><div class="fields">${input('amount','Valor líquido da oferta · R$',ride.amount,'type="number" min="0" step=".01" required')}${input('tripKm','Km com passageiro',ride.tripKm,'type="number" min="0" step="any" required')}${input('pickupKm','Km até o passageiro',ride.pickupKm,'type="number" min="0" step="any" required')}${input('tripMin','Minutos da viagem',ride.tripMin,'type="number" min="0" step="any" required')}${input('pickupMin','Minutos até o passageiro',ride.pickupMin,'type="number" min="0" step="any" required')}${input('toll','Pedágio não reembolsado · R$',ride.toll,'type="number" min="0" step=".01" required')}</div><details><summary>Espera e reposicionamento após a viagem</summary><div class="fields">${input('waitMin','Minutos de espera',ride.waitMin,'type="number" min="0" step="any" required')}${input('returnKm','Km de retorno/reposição',ride.returnKm,'type="number" min="0" step="any" required')}${input('returnMin','Minutos de retorno/reposição',ride.returnMin,'type="number" min="0" step="any" required')}</div></details><p id="ride-error" class="form-error" role="alert" hidden></p></form><div id="ride-result" aria-live="polite">${rideResultBody()}</div><div class="actions gap">${btn('Registrar que aceitei','accept-ride','primary')}${btn('Registrar que recusei','reject-ride')}</div><p class="caption">Os botões só registram sua decisão nesta demonstração. Não enviam nenhuma ação para aplicativos de corrida.</p>${link('Ajustar minhas metas, consumo e custos →','driver-goals')}<details><summary>Minhas decisões registradas (${ops.personal.offers.length})</summary>${ops.personal.offers.slice().reverse().map(o=>row(o.choice==='accepted'?'Aceitei':'Recusei',cash(o.amount),cash(o.netKm)+'/km líquido · '+cash(o.netHour)+'/h · '+(o.meets?'atingia as metas':'abaixo das metas'))).join('')||'<p class="caption">Ainda sem decisão registrada.</p>'}</details>`;}
 function rideResultBody(){const r=rideResult;if(!r)return '<div class="notice amber">Revise os campos para calcular. Informe tempo e distância maiores que zero.</div>';return `<section class="ride-result ${r.meets?'':'negative'}"><p class="result-word">${r.meets?'Essa oferta atinge suas metas.':'Essa oferta fica abaixo das suas metas.'}</p><div class="ride-metrics"><div><strong>${cash(r.netKm)}</strong><small>POR KM LÍQUIDO · META ${cash(Math.max(r.p.minNetKm,r.goalKm))}</small></div><div><strong>${money(r.netHour)}</strong><small>POR HORA LÍQUIDA · META ${money(Math.max(r.p.minNetHour,r.goalHour))}</small></div></div><p class="caption">${num(r.km)} km totais · ${num(r.minutes)} minutos totais. ${r.meets?'Você decide se faz sentido para este momento.':r.reasons.map(esc).join(' · ')+'.'}</p></section><div class="gap">${panel('A conta da corrida',row('Oferta que você receberá',cash(r.o.amount))+row('Combustível estimado',cash(-r.fuel))+row('Outros custos por km',cash(-r.variable))+row('Aluguel rateado pelo tempo',cash(-r.rent))+row('Pedágio não reembolsado',cash(-r.o.toll))+row('Sobra líquida estimada',cash(r.net),'Após os custos acima; depende das premissas.',true)+row('Oferta mínima para suas metas',cash(r.minimumOffer),'O maior requisito entre R$/km, R$/h e meta diária convertida por km e tempo.')+row('Falta na oferta atual',cash(r.gap)))}</div>`;}
 function updateRide(){const form=root.querySelector('#ride-form');if(!form)return;const values=Object.fromEntries(new FormData(form));for(const key of Object.keys(values))values[key]=Number(values[key]);try{const calculated=D.evaluate(values,ops.personal.settings);ride=values;rideResult=calculated;root.querySelector('#ride-error').hidden=true;}catch(error){rideResult=null;const element=root.querySelector('#ride-error');element.hidden=false;element.textContent=error.message;}root.querySelector('#ride-result').innerHTML=rideResultBody();}
 function driverAction(action,e){if(action.startsWith('driver-')&&driverNames[action.slice(7)]){driverPage=action.slice(7);mode='driver';close();render();persist();return true;}
 if(action==='accept-ride'||action==='reject-ride'){updateRide();if(!rideResult)throw new RangeError('Revise a oferta antes de registrar a decisão.');ops.personal.offers.push({at:new Date().toISOString(),...ride,choice:action==='accept-ride'?'accepted':'rejected',net:rideResult.net,netKm:rideResult.netKm,netHour:rideResult.netHour,meets:rideResult.meets});render();persist();toast('Decisão registrada só no seu histórico pessoal.');return true;}
 if(action==='proof'){M.proof(ops,e.dataset.id,'Envio ilustrativo pelo motorista · '+e.dataset.id);render();persist();toast('Comprovante em análise. O aluguel só baixa depois da conferência.');return true;}return false;}
 function driverSubmit(form,f){const n=key=>Number(f.get(key));let handled=true;
 if(form.id==='goals-form'){const next={};for(const key of Object.keys(D.defaults))next[key]=n(key);ops.personal.settings=D.validate(next);rideResult=D.evaluate(ride,next);}
 else if(form.id==='journey-form'){M.saveJourney(ops,{date:String(f.get('date')),amount:n('amount'),fuel:n('fuel'),other:n('other'),km:n('km'),hours:n('hours')});}
 else if(form.id==='maintenance-request-form'){M.request(ops,{type:'maintenance',priority:f.get('priority'),note:f.get('note')});}
 else if(form.id==='stock-request-form'){const productId=f.get('productId'),p=ops.book.products.find(p=>p.id===productId);M.request(ops,{type:'stock',productId,qty:n('qty'),note:'Reposição de '+n('qty')+' × '+p.name});}
 else if(form.id==='inspection-form'){M.inspect(ops,{km:n('km'),note:f.get('note'),checks:[0,1,2,3].map(i=>f.has('check'+i))});}
 else if(form.id==='support-form'){M.request(ops,{type:'support',subject:f.get('subject'),note:f.get('note')});}
 else handled=false;if(handled){render();persist();toast('Registro salvo na sua área de demonstração.');}return handled;}
